class Solution:
    def findLengthOfLCIS(self, nums: list[int]) -> int:
        lengths = [1] * len(nums)
        for i in range(1, len(nums)):
            if nums[i] > nums[i - 1]:
                lengths[i] = lengths[i - 1] + 1
        return max(lengths, default=0)
